def minDeletions(nums):
    count = {}
    for x in nums:
        count[x] = count.get(x, 0) + 1
    cc = [0] * (len(nums) + 1)
    for c in count.values():
        cc[c] += 1
    deletions = 0
    extra = 0
    for f in range(len(nums), 0, -1):
        total = cc[f] + extra
        if total > 0:
            extra = total - 1
            deletions += extra
        else:
            extra = 0
    return deletions
